    with pytest.raises(RuntimeError, match="db unavailable"):
        with TestClient(app):
            pass  # pragma: no cover


def test_startup_error_captured_with_callback() -> None:
    """With a custom `on_startup_error` callback, the exception raised by a
    startup handler is passed to the callback instead of propagating, and
    startup completes normally so the app can serve requests."""
    captured: list[Exception] = []

    def on_startup_error(exc: Exception) -> None:
        captured.append(exc)

    def failing_startup() -> None:
        raise RuntimeError("db unavailable")

    app = FastAPI(
        on_startup=[failing_startup],
        on_startup_error=on_startup_error,
    )

    @app.get("/ping")
    def ping() -> dict[str, str]:
        return {"pong": "ok"}

    with TestClient(app) as client:
        response = client.get("/ping")

    assert len(captured) == 1
    assert isinstance(captured[0], RuntimeError)
    assert str(captured[0]) == "db unavailable"
    assert response.status_code == 200
    assert response.json() == {"pong": "ok"}

